    tintMint: 'linear-gradient(135deg, #DCEBE1 0%, #EEF5F0 100%)', tintSage: 'linear-gradient(135deg, #E6F0E8 0%, #F3F8F4 100%)', tintMintLine: '#C9DCCF',
