                {nudge === i && <circle className="edu-still-sign" cx={part[2]} cy={part[3]} r={part[4] * 0.9} fill="none" stroke={B.clay} strokeWidth="1.6" strokeDasharray="2.5 1.5" />}
                {piece(part)}
