// Where the pictures go (Mikey, 08:05: "inside of the card and around the text ... we don't have anything directly left or right
// of the text"): inside the card, in a band above the words and a band below them, never beside the words, so the words keep the
// card's whole width. Two or three sit in the band above and the rest below, each at its own place across the card, its own size
// and its own angle, sized and placed by its turned box so it stays in its band and never touches a word; each falls or rises in
// from the card's edge with a little bounce, then is still, and with motion off it is simply there. The scatter comes from the
// question's id, so one question always looks the same and the next one different.
const PONDER_FROM = { top: [0, -60], bottom: [0, 60] };
// The pictures' ink: the card's own text color, softened, so they read as part of the card and never compete with its words.
const ponderInk = () => C.ink;
function PonderFrame({ seed = 1, children, style = null, attrs = null, className }) {
  const vw = typeof window !== 'undefined' ? window.innerWidth : 390;
  const wide = vw >= 700;
  const band = wide ? 74 : 56;   // the room inside the card, above and below the words, that the pictures live in
  const icons = useMemo(() => {
    const rnd = lcg(seed); const names = shuffle(rnd, Object.keys(PONDER_ICONS)).slice(0, 6);
    const lo = wide ? 46 : 36; const hi = wide ? 64 : 48;
    const above = rnd() < 0.7 ? 2 : 3;
    const spread = (n, where) => Array.from({ length: n }, (_, j) => [where, (j + 0.5) / n + (rnd() - 0.5) * (0.6 / n)]);
    const spots = [...spread(above, 'top'), ...spread(6 - above, 'bottom')];
    return names.map((nm, i) => {
      // A turned picture's box is wider than the picture (a square turned 25 degrees is a third wider), so each is sized and placed
      // by its turned box, which stays inside its band.
      const [where, at0] = spots[i]; const rot = Math.round((rnd() - 0.5) * 44); const [fx, fy] = PONDER_FROM[where];
      const turn = Math.abs(Math.cos((rot * Math.PI) / 180)) + Math.abs(Math.sin((rot * Math.PI) / 180));
      const size = Math.min(Math.floor((band - 6) / turn), Math.round(lo + rnd() * (hi - lo)));
      const ext = Math.ceil((size * turn - size) / 2);
      return { nm, where, at: Math.min(0.86, Math.max(0.14, at0)), size, off: ext + 2 + Math.round(rnd() * Math.max(0, band - size - 2 * ext - 4)), rot, wait: (0.15 + i * 0.12 + rnd() * 0.1).toFixed(2), fx: fx + Math.round((rnd() - 0.5) * 40), fy: fy + Math.round((rnd() - 0.5) * 20) };
    });
  }, [seed, wide, band]);
  const placeOf = (ic) => (ic.where === 'top' ? { left: `calc(${(ic.at * 100).toFixed(1)}% - ${Math.round(ic.size / 2)}px)`, top: ic.off }
    : { left: `calc(${(ic.at * 100).toFixed(1)}% - ${Math.round(ic.size / 2)}px)`, bottom: ic.off });
  return (
    <div {...(attrs || {})} data-ponder-frame="" className={className} style={{ ...(style || {}), position: 'relative', overflow: 'hidden', paddingTop: band, paddingBottom: band }}>
      <div aria-hidden="true" data-ponder-pictures="" style={{ position: 'absolute', top: 0, right: 0, bottom: 0, left: 0, pointerEvents: 'none', zIndex: 0, color: ponderInk() }}>
        {icons.map((ic) => (
          <svg key={ic.nm} data-ponder-icon={ic.nm} className="edu-ponder-icon" viewBox="0 0 64 64" width={ic.size} height={ic.size}
            style={{ ...placeOf(ic), '--pr': `${ic.rot}deg`, '--po': '0.55', '--pd': `${ic.wait}s`, '--px': `${ic.fx}px`, '--py': `${ic.fy}px` }}>
            {PONDER_ICONS[ic.nm]()}
          </svg>
        ))}
      </div>
      <div style={{ position: 'relative', zIndex: 1 }}>{children}</div>
    </div>
  );
}
// A number from a Wonder question's id, so its scatter of pictures is its own and the same on every visit.
function seedOf(text) { let h = 7; for (const ch of String(text || '')) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return h || 7; }
// The closing card (pass MH): the rotating title from logic (ponderTitle) above the closing line, the pondering pictures around
// it. A pre-reader meets it as the last card; a reader at the foot of the voices.
function PonderCard({ wonder, title, text, big = false, attrs = null }) {
  return (
    <PonderFrame seed={seedOf(`${wonder.id}-closing`)} attrs={attrs} className="edu-rise" style={{ ...card, background: C.goldSoft, borderColor: C.goldEdge, textAlign: 'center', padding: big ? '20px 18px 22px' : '14px 16px 16px', margin: '0 0 14px' }}>
        <p data-ponder-title="" className="edu-ponder-title" style={{ margin: '0 0 8px', fontSize: big ? 24 : 19, fontWeight: 800, letterSpacing: '0.01em', color: C.mode === 'dark' ? '#E9C46A' : C.green }}>{title}</p>
        <p style={{ fontSize: big ? 20 : 16, lineHeight: 1.5, margin: 0 }}>{text}</p>
    </PonderFrame>
  );
}

function Tag({ children, tone }) {
  const tones = { mastered: [C.goldSoft, C.gold], passed: [C.goldSoft, C.gold], available: [C.greenSoft, C.green], locked: [C.mode === 'dark' ? 'rgba(241, 237, 227, 0.1)' : '#EEF0EA', C.muted], review: [C.claySoft, C.clayInk] };
  const [bg, fg] = tones[tone] || tones.locked;
  return <span style={{ display: 'inline-block', background: bg, color: fg, fontSize: 13, fontWeight: 600, lineHeight: '18px', padding: '4px 10px', borderRadius: 999, whiteSpace: 'nowrap', textAlign: 'center' }}>{children}</span>;
}

function fmtDate(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + ' ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
}

// ---------- Storage helpers (all reads/writes go through these) ----------
// Rules: keys use only letters, numbers and underscores; every save is also kept
// in memory for the session, so a failed save never breaks the lesson; a failed
// save is retried once after a short pause (the storage API is rate limited).
const STORE_PREFIX = 'edusphere_v1_learner_';
const slug = (name) => name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const sessionCopy = new Map();
const hasStorage = () => typeof window !== 'undefined' && window.storage && typeof window.storage.set === 'function';
const pause = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function storageGet(key) {
  if (sessionCopy.has(key)) return sessionCopy.get(key);
  if (!hasStorage()) return null;
  try {
    const r = await window.storage.get(key, false);
    return r && typeof r.value === 'string' ? r.value : null;
  } catch (e) { return null; } // a missing key throws; that just means "new learner"
}
async function storageDelete(key) {
  sessionCopy.delete(key);
  if (!hasStorage()) return { saved: false, reason: 'no storage on this page' };
  try { await window.storage.delete(key, false); return { saved: true }; } catch (e) { return { saved: false, reason: (e && e.message) || 'unknown error' }; }
}
async function storageSet(key, value) {
  sessionCopy.set(key, value);
  if (!hasStorage()) return { saved: false, reason: 'no storage on this page' };
  for (let tryNo = 1; tryNo <= 2; tryNo++) {
    try {
      const r = await window.storage.set(key, value, false);
      if (r) return { saved: true };
    } catch (e) {
      if (tryNo === 2) return { saved: false, reason: (e && e.message) || 'unknown error' };
    }
    await pause(600);
  }
  return { saved: false, reason: 'no response' };
}
// -----------------------------------------------------------------------------------------------------------------
// Where the student was (2026-09-30, pass GV, Mikey). In plain terms: when a student is on their overview, in a lesson,
// on a story or on the map, the app writes a small note to the browser ("Ava, lesson, fractions") so that a page
// refresh brings them straight back there instead of to the front door. Educator screens are never remembered,
// because they sit behind the PIN, and the note is erased when the student taps Exit. Storage may be switched off in
// some browsers, so every read and write is wrapped in try.
// -----------------------------------------------------------------------------------------------------------------
const WHERE_KEY = 'edusphere_v1_where';
const WHERE_SCREENS = new Set(['overview', 'lesson', 'story', 'map', 'practice']); // 'practice' since pass HR: a set in progress resumes after a refresh
function loadWhere() { try { const w = safeJson(window.localStorage.getItem(WHERE_KEY)); return w && typeof w.name === 'string' && w.name && WHERE_SCREENS.has(w.screen) ? w : null; } catch (e) { return null; } }
function saveWhere(w) { try { if (w) window.localStorage.setItem(WHERE_KEY, JSON.stringify(w)); else window.localStorage.removeItem(WHERE_KEY); } catch (e) { /* storage may be off */ } }
async function loadRecord(name) {
  const raw = await storageGet(STORE_PREFIX + slug(name));
  if (raw) { const r = safeJson(raw); if (r) return r; }   // unreadable: fall through to a fresh record
  return { version: 1, name: name.trim(), createdAt: new Date().toISOString(), events: [] };
}
async function saveRecord(record) {
  return storageSet(STORE_PREFIX + slug(record.name), JSON.stringify(record));
}
// The roster lives under one key. Students never create themselves; an admin does.
const ROSTER_KEY = 'edusphere_v1_roster';
async function loadRoster() {
  const raw = await storageGet(ROSTER_KEY);
  if (raw) { const r = safeJson(raw); if (r && Array.isArray(r.students)) return r; }
  return emptyRoster();
}
async function saveRoster(roster) { return storageSet(ROSTER_KEY, JSON.stringify(roster)); }

// Which life skills this classroom has covered. Nothing about any student is stored here.
const COVERED_KEY = 'edusphere_v1_covered_skills';
async function loadCovered() {
  const raw = await storageGet(COVERED_KEY);
  if (raw) { const c = safeJson(raw); if (c && Array.isArray(c.covered)) return c; }
  return emptyCoveredSkills();
}
async function saveCovered(state) { return storageSet(COVERED_KEY, JSON.stringify(state)); }

// Which reflection questions this school has read and approved.
const WONDER_KEY = 'edusphere_v1_wonder_review';
async function loadWonderReview() {
  const raw = await storageGet(WONDER_KEY);
  if (raw) { const r = safeJson(raw); if (r && Array.isArray(r.approved)) return r; }
  return emptyWonderReview();
}
async function saveWonderReview(state) { return storageSet(WONDER_KEY, JSON.stringify(state)); }

// When the classroom was last backed up to a file, so the app can nag gently.
const BACKUP_AT_KEY = 'edusphere_v1_last_backup';
async function loadBackupAt() { return (await storageGet(BACKUP_AT_KEY)) || null; }
async function saveBackupAt(at) { return storageSet(BACKUP_AT_KEY, at); }
// The educator's own PIN, kept on this device. A convenience lock rather than security,
// exactly as before, but now the educator chooses it. Stored scrambled so it is not
// sitting in plain sight in the browser's storage.
const EDUCATOR_KEY = 'edusphere_v1_educator';
// A backup file larger than this is refused before it is read (a real classroom backup is a few megabytes).
const BACKUP_MAX_BYTES = 50 * 1024 * 1024;
